{
  "flow": {
    "name": "Sarkari Exam AI",
    "url": "https://app.banani.co/flow/wqucLs7TJesh",
    "id": "wqucLs7TJesh"
  },
  "designs": [
    {
      "screenId": "wqucLs7TJesh/screens/new_screen7.jsx",
      "screenName": "AI Tools Dashboard",
      "source": "import Icon from '@global/Icon';
import UserAvatar from '@global/UserAvatar';

export const displayName = 'AI Tools Dashboard';
export const screenSize = 'mobile';

export default function AIToolsDashboardScreen() {
  const tools = [
    { title: t('Notes Generator'), subtitle: t('Smart PDF to Notes'), icon: 'file-text', color: 'text-blue-600', bg: 'bg-blue-50' },
    { title: t('Study Planner'), subtitle: t('Personalized schedule'), icon: 'calendar', color: 'text-purple-600', bg: 'bg-purple-50' },
    { title: t('Past Paper Analyzer'), subtitle: t('Trend insights'), icon: 'search', color: 'text-amber-600', bg: 'bg-amber-50' },
    { title: t('PYQ Generator'), subtitle: t('Custom test sets'), icon: 'refresh-cw', color: 'text-green-600', bg: 'bg-green-50' },
    { title: t('Weak Topic Analyzer'), subtitle: t('Find your gaps'), icon: 'bar-chart-2', color: 'text-rose-600', bg: 'bg-rose-50' },
    { title: t('AI Mock Test'), subtitle: t('Adaptive difficulty'), icon: 'file-edit', color: 'text-indigo-600', bg: 'bg-indigo-50' },
    { title: t('Flashcard Generator'), subtitle: t('Active recall'), icon: 'layers', color: 'text-teal-600', bg: 'bg-teal-50' },
    { title: t('Revision Booster'), subtitle: t('Quick summaries'), icon: 'zap', color: 'text-orange-500', bg: 'bg-orange-50' },
  ];

  return (
    <div className="flex flex-col h-full bg-input relative mobile-screen overflow-hidden">

      {/* Top Bar */}
      <header className="flex items-center justify-between px-5 py-4 bg-white border-b border-border z-20 shadow-[0_2px_10px_-4px_rgba(0,0,0,0.05)] flex-shrink-0 sticky top-0">
        <h1 className="font-headings font-bold text-xl text-foreground flex items-center gap-2">
          {t('AI Tools 🤖')}
        </h1>
        <div className="flex items-center gap-4">
          <button className="text-muted-foreground hover:text-foreground transition-colors p-1">
            <Icon i="search" size={22} />
          </button>
          <button className="border-2 border-border rounded-full overflow-hidden hover:border-primary transition-colors">
            <UserAvatar gender="male" ageGroup="18-25" heritage="South Asian" index={1} className="w-8 h-8" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-6">
        <div className="px-5 py-6 space-y-6">

          {/* Featured AI Card */}
          <div className="bg-gradient-to-br from-primary to-blue-800 rounded-3xl p-6 shadow-md relative overflow-hidden flex flex-col justify-between min-h-[140px]">
            <div className="absolute top-0 right-0 p-4 opacity-[0.15] text-white">
              <Icon i="sparkles" size={80} />
            </div>
            <div className="relative z-10 max-w-[80%]">
              <h2 className="text-xl font-bold font-headings text-white mb-2 leading-snug">
                {t('Generate Notes from PYQ / PDF instantly')}
              </h2>
            </div>
            <div className="relative z-10 mt-4">
              <button className="bg-white text-primary px-5 py-2.5 rounded-xl text-sm font-bold shadow-sm inline-flex items-center gap-1.5 hover:bg-white/90 transition-colors">
                {t('Try Now')} <Icon i="arrow-right" size={16} />
              </button>
            </div>
          </div>

          {/* User Performance & Smart Suggestion */}
          <div className="grid grid-cols-1 gap-4">

            {/* Performance Card */}
            <div className="bg-white border border-border rounded-2xl p-5 shadow-sm flex flex-col gap-3">
              <div className="flex justify-between items-center">
                <h3 className="font-bold text-sm text-foreground flex items-center gap-1.5">
                  <Icon i="target" size={16} className="text-primary" /> {t('Your Performance')}
                </h3>
                <span className="font-bold text-lg text-success">72%</span>
              </div>
              <div className="h-2 w-full bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-success rounded-full" style={{ width: '72%' }}></div>
              </div>
            </div>

            {/* Smart Suggestion */}
            <div className="bg-warning-muted border border-warning/20 rounded-2xl p-5 shadow-sm flex items-start gap-3">
              <div className="bg-warning/20 text-warning-text p-2 rounded-full mt-0.5">
                <Icon i="lightbulb" size={16} />
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-warning-text mb-3">
                  {t('Based on your weak topics → Practice Polity')}
                </p>
                <button className="bg-warning text-white px-4 py-2 rounded-lg text-xs font-bold shadow-sm hover:opacity-90 transition-opacity">
                  {t('Start Practice')}
                </button>
              </div>
            </div>
          </div>

          {/* AI Tools Grid */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-foreground text-base">{t('AI Capabilities')}</h3>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {tools.map((tool, idx) => (
                <button key={idx} className="bg-white border border-border p-4 rounded-2xl shadow-sm flex flex-col items-start text-left hover:border-primary/40 transition-colors group">
                  <div className={`${tool.bg} ${tool.color} p-3 rounded-xl mb-3 group-hover:scale-105 transition-transform`}>
                    <Icon i={tool.icon} size={20} />
                  </div>
                  <span className="font-bold text-sm text-foreground leading-tight mb-1">{tool.title}</span>
                  <span className="text-[10px] text-muted-foreground font-medium">{tool.subtitle}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Mini Weak Topic Panel & Recent Activity */}
          <div className="grid grid-cols-1 gap-4 pb-2">

            {/* Weak Topics */}
            <div className="bg-white border border-border rounded-2xl p-5 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-bold text-sm text-foreground flex items-center gap-1.5">
                  <Icon i="trending-down" size={16} className="text-error" /> {t('Weak Topics')}
                </h3>
              </div>
              <div className="space-y-4">
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="font-medium text-foreground">{t('Math')}</span>
                    <span className="text-error font-bold">40%</span>
                  </div>
                  <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                    <div className="h-full bg-error rounded-full" style={{ width: '40%' }}></div>
                  </div>
                </div>
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="font-medium text-foreground">{t('Polity')}</span>
                    <span className="text-warning-text font-bold">55%</span>
                  </div>
                  <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                    <div className="h-full bg-warning rounded-full" style={{ width: '55%' }}></div>
                  </div>
                </div>
              </div>
              <button className="w-full mt-5 py-2.5 bg-primary/10 text-primary font-bold rounded-xl text-xs hover:bg-primary/20 transition-colors">
                {t('Improve Now')}
              </button>
            </div>

            {/* Recent Activity */}
            <div className="bg-white border border-border rounded-2xl p-5 shadow-sm">
              <h3 className="font-bold text-sm text-foreground mb-4">{t('Recent Activity')}</h3>
              <div className="space-y-4">
                <div className="flex items-start gap-3">
                  <div className="bg-blue-50 text-blue-600 p-2 rounded-full">
                    <Icon i="file-text" size={14} />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-foreground">{t('Notes Generated')}</h4>
                    <p className="text-xs text-muted-foreground">{t('Fundamental Rights PDF')}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <div className="bg-indigo-50 text-indigo-600 p-2 rounded-full">
                    <Icon i="file-edit" size={14} />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-foreground">{t('Mock Test Attempted')}</h4>
                    <p className="text-xs text-muted-foreground">{t('SSC CGL Tier 1 (2022)')}</p>
                  </div>
                </div>
              </div>
            </div>

          </div>

        </div>
      </main>

      {/* Custom Bottom Nav for this Screen */}
      <div className="flex items-center justify-between px-2 py-2 bg-white border-t border-border z-20 pb-safe">
        {[
          { name: t('Home'), icon: 'home' },
          { name: t('Tests'), icon: 'file-text' },
          { name: t('AI Tools'), icon: 'bot' },
          { name: t('Results'), icon: 'pie-chart' },
          { name: t('Profile'), icon: 'user' },
        ].map((tab) => {
          const isActive = tab.name === t('AI Tools');
          return (
            <button 
              key={tab.name}
              className={`flex flex-col items-center justify-center w-full py-1.5 gap-1 rounded-xl transition-colors ${
                isActive ? 'text-primary' : 'text-muted-foreground hover:bg-muted/50'
              }`}
            >
              <div className={`p-1.5 rounded-full ${isActive ? 'bg-primary/10' : 'bg-transparent'}`}>
                <Icon i={tab.icon} size={20} className={isActive ? 'fill-primary/20' : ''} />
              </div>
              <span className={`text-[10px] ${isActive ? 'font-bold' : 'font-medium'}`}>
                {tab.name}
              </span>
            </button>
          );
        })}
      </div>

    </div>
  );
}",
      "genType": "components"
    }
  ],
  "sharedFiles": [
    {
      "path": "/style.css",
      "content": "@theme {
  /* used via utility-classes, bg-background, text-primary, and many more */
  --color-background: #ffffff;
  --color-foreground: #435f96;
  --color-border: #e2e8f0;
  --color-input: #f8fafc;
  --color-primary: #1a55b4;
  --color-primary-foreground: #ffffff;
  --color-secondary: #eff6ff;
  --color-secondary-foreground: #1e40af;
  --color-muted: #f1f5f9;
  --color-muted-foreground: #64748b;

  /* Semantic Status Colors */
  --color-error: #ef4444;
  --color-error-foreground: #ffffff;
  --color-error-muted: #fef2f2;
  --color-success: #10b981;
  --color-success-foreground: #ffffff;
  --color-success-muted: #ecfdf5;
  --color-warning: #f59e0b;
  --color-warning-text: #b45309;
  --color-warning-muted: #fef3c7;

  /* Premium Paywall Colors */
  --color-premium-bg: #0b0b1b;
  --color-premium-card: #020805;
  --color-premium-border: #dadae7;
  --color-premium-text: #ffffff;
  --color-premium-muted: #a1a1aa;
  --color-premium-gold: #fbbf24;
  --color-premium-gold-dark: #d97706;
  --color-premium-purple: #bca7cf;
  --color-premium-purple-light: #a855f7;

  /* DO NOT REMOVE: these radius variables are required by the theme editor. */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-2xl: 32px;

  /* DONT CHANGE OR REMOVE THIS VARIABLE */
  --radius: var(--radius-md);

  /* DO NOT REMOVE: these font variables are required by the theme editor. */
  --font-body: Inter;
  --font-headings: Inter;

  /* Add and change text sizes as you see fit */
  --text-xs: 12px;
  --text-sm: 14px;
  --text-base: 16px;
  --text-lg: 18px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 36px;
}"
    }
  ]
}
